import type { ComponentDefinition, ComponentSet } from '../domain/types';
import { deepFreezeComponentSets } from './builtin';
import { COMPONENT_PRESENTATION_KEY } from './isometric';

/**
 * The Lucide icons (https://lucide.dev, ISC) as component sets (#227), generated by scripts/import-lucide-icons.mjs.
 * They are generic components drawn as free-standing figures, like the isometric icons: no new provider in the
 * document model. One set per Lucide category, so a document only embeds the categories it uses.
 */
export interface RawLucideComponent { type: string; name: string; aliases?: string[]; iconSvg: string }
export interface RawLucideSet { id: string; name: string; version: string; category: string; components: RawLucideComponent[] }
export interface RawLucideLibrary { package: string; license: string; retrieved: string; sets: RawLucideSet[] }

export const LUCIDE_SET_PREFIX = 'sketchdraw.lucide.';
export const LUCIDE_PROVENANCE = 'lucide-icon';

export function isLucideComponent(component: Pick<ComponentDefinition, 'metadata'>): boolean {
  return component.metadata?.['provenance'] === LUCIDE_PROVENANCE;
}

export function toLucideComponentSets(library: RawLucideLibrary): ComponentSet[] {
  return deepFreezeComponentSets(library.sets.map((set) => ({
    id: set.id,
    name: set.name,
    version: set.version,
    components: set.components.map((component): ComponentDefinition => ({
      type: component.type,
      name: component.name,
      provider: 'generic',
      category: set.category,
      ...(component.aliases?.length ? { aliases: component.aliases } : {}),
      defaultWidth: 64,
      defaultHeight: 82,
      // The lines of the icon take the stroke colour of the element; there is no card around it.
      style: { stroke: '#1e293b', fill: 'transparent', strokeWidth: 0, fontSize: 12, textAlign: 'center' },
      metadata: { provenance: LUCIDE_PROVENANCE, source: 'https://lucide.dev', license: library.license, package: library.package, [COMPONENT_PRESENTATION_KEY]: 'icon' },
      iconSvg: component.iconSvg,
    })),
  })));
}
